// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address nonWard, address targetUser) public {
        vm.assume(nonWard != address(this));
        vm.assume(targetUser != address(0));
        vm.assume(nonWard != targetUser);

        vm.prank(nonWard);
        try c.rely(targetUser) { } catch { }

        uint256 wardStatus = c.wards(targetUser);
        assertTrue(wardStatus == 0);
    }
}
